# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of _upsample_nearest_exact3d_backward (grad_input out variant).

Semantics (ATen):
  fwd_x(j) = min(int(floorf((j + 0.5f) * s_x)), in_x - 1),
  s_x = float32(in_x) / float32(out_x)  (or float32(1 / scales_x) when scales_x > 0)
  grad_input[n, c, i_d, i_h, i_w] = sum over all (j_d, j_h, j_w) with
      fwd_d(j_d) == i_d, fwd_h(j_h) == i_h, fwd_w(j_w) == i_w of
      grad_output[n, c, j_d, j_h, j_w]

The many-to-one pre-image of input index i along a dimension is the half-open
interval [ceil(i * r - 0.5), ceil((i + 1) * r - 0.5)) with r = out/in, which in
exact integer arithmetic is

    start = (2 * i * out + in - 1) // (2 * in)
    end   = (2 * (i + 1) * out + in - 1) // (2 * in)
    fwd(j) = (2 * j * in + in) // (2 * out)

Both bounds land inside [0, out] automatically.  Evaluating them in integers
removes every floating-point index decision, which on this target is both faster
and immune to fp32 rounding at a boundary.

Three device paths, all single-launch, one read of grad_output and exactly one
grad_input write per element (no zero-fill pass, no atomics):
  * integer upsampling factor out == in*k: the pre-image is the contiguous box
    [i*k, (i+1)*k), handled by fully coalesced BLOCK_W*FW vector loads plus a
    reduction over the innermost axis.
  * general rational factor: one program per (n, c, i_d, i_h, w-tile); contiguous
    vector loads along W plus an exact integer forward-map equality matrix; the
    d/h windows are scalar integer loops with no floating-point arithmetic at all.
  * provided scales that disagree with out/in: exact fp32 forward-map predicate
    gather (slow, but exact and never reached for size-consistent scales).
"""

import struct
from typing import Optional, Tuple

import torch
import triton
import triton.language as tl


@triton.jit
def _exact3d_bwd_int_kernel(
    go_ptr,
    gi_ptr,
    Wi,
    W_TILES,
    C,
    Hi,
    Di,
    sgo_n,
    sgo_c,
    sgo_d,
    sgo_h,
    sgi_n,
    sgi_c,
    sgi_d,
    sgi_h,
    sgi_w,
    FD: tl.constexpr,
    FH: tl.constexpr,
    FW: tl.constexpr,
    FWP: tl.constexpr,
    FW_POW2: tl.constexpr,
    BLOCK_W: tl.constexpr,
    EVEN_W: tl.constexpr,
    IS_FP64: tl.constexpr,
):
    pid = tl.program_id(0)
    pw = pid % W_TILES
    t = pid // W_TILES
    ih = t % Hi
    t = t // Hi
    id_ = t % Di
    t = t // Di
    c = t % C
    n = t // C

    if IS_FP64:
        acc = tl.zeros((BLOCK_W,), dtype=tl.float64)
    else:
        acc = tl.zeros((BLOCK_W,), dtype=tl.float32)

    go_base = n * sgo_n + c * sgo_c
    od0 = id_ * FD
    oh0 = ih * FH
    w0 = pw * BLOCK_W

    if FW_POW2:
        woff = w0 * FW + tl.arange(0, BLOCK_W * FW)
        for kd in tl.static_range(FD):
            for kh in tl.static_range(FH):
                p = go_ptr + go_base + (od0 + kd) * sgo_d + (oh0 + kh) * sgo_h + woff
                if EVEN_W:
                    v = tl.load(p)
                else:
                    v = tl.load(p, mask=woff < Wi * FW, other=0.0)
                if FW == 1:
                    if IS_FP64:
                        acc += v
                    else:
                        acc += v.to(tl.float32)
                else:
                    v2 = tl.reshape(v, (BLOCK_W, FW))
                    if IS_FP64:
                        acc += tl.sum(v2, axis=1)
                    else:
                        acc += tl.sum(v2.to(tl.float32), axis=1)
    else:
        iwv = w0 + tl.arange(0, BLOCK_W)
        kk = tl.arange(0, FWP)
        woff2 = iwv[:, None] * FW + kk[None, :]
        m2 = (kk < FW)[None, :] & (iwv < Wi)[:, None]
        for kd in tl.static_range(FD):
            for kh in tl.static_range(FH):
                p = go_ptr + go_base + (od0 + kd) * sgo_d + (oh0 + kh) * sgo_h + woff2
                v = tl.load(p, mask=m2, other=0.0)
                if IS_FP64:
                    acc += tl.sum(v, axis=1)
                else:
                    acc += tl.sum(v.to(tl.float32), axis=1)

    iw = w0 + tl.arange(0, BLOCK_W)
    gi_off = n * sgi_n + c * sgi_c + id_ * sgi_d + ih * sgi_h + iw * sgi_w
    res = acc.to(gi_ptr.dtype.element_ty)
    if EVEN_W:
        tl.store(gi_ptr + gi_off, res)
    else:
        tl.store(gi_ptr + gi_off, res, mask=iw < Wi)


@triton.jit
def _exact3d_bwd_down_pack_kernel(
    go_ptr,
    giw_ptr,
    C,
    Hi,
    Ho,
    sgo_n,
    sgo_c,
    sgo_d,
    sgo_h,
    sgw_n,
    sgw_c,
    sgw_d,
    sgw_h,
    KD: tl.constexpr,
    KH: tl.constexpr,
    OW: tl.constexpr,
    OWP: tl.constexpr,
    MODE: tl.constexpr,
    R: tl.constexpr,
):
    """Integer downsampling with KW == 2 written through an int32 word view.

    With in == out*2 the W pattern is grad_input[2j+1] = grad_output[j] and
    grad_input[2j] = 0.  Reinterpreting grad_input as 32-bit words turns each
    such pair into two adjacent words, so a row needs only flat 1-D stores:

      * MODE 0 (16-bit data): one packed word (payload << 16) per pair, written
        contiguously -- no (OWP, 2) broadcast, no tl.reshape, no UB-to-UB block
        copies and no per-row sync chain;
      * MODE 1 (32-bit data): the payload word at the odd offsets and a zero
        word at the even offsets, two stride-2 stores (64-bit words measured
        ~3.5x more per row than this on this backend).

    Rows without a pre-image store zeros, so every grad_input element is
    written exactly once whatever the destination held before.
    """
    ih0 = tl.program_id(0) * R
    id_ = tl.program_id(1)
    nc = tl.program_id(2)
    c = nc % C
    n = nc // C

    jd_num = id_ - (KD // 2)
    jd = jd_num // KD
    okd = (jd_num >= 0) & (jd_num % KD == 0)

    go_base = n * sgo_n + c * sgo_c + jd * sgo_d
    gw_base = n * sgw_n + c * sgw_c + id_ * sgw_d

    jcols = tl.arange(0, OWP)
    jjc = tl.minimum(jcols, OW - 1)

    rmax = tl.minimum(R, Hi - ih0)
    for r in range(rmax):
        ih = ih0 + r
        hnum = ih - (KH // 2)
        jh = hnum // KH
        ok = okd & (hnum >= 0) & (hnum % KH == 0)
        jhc = tl.maximum(tl.minimum(jh, Ho - 1), 0)
        v = tl.load(go_ptr + go_base + jhc * sgo_h + jjc)
        v = tl.where(ok, v, 0.0)
        off = gw_base + ih * sgw_h
        if MODE == 0:
            pk = v.to(tl.uint16, bitcast=True).to(tl.uint32) << 16
            tl.store(
                giw_ptr + off + jcols,
                pk.to(tl.int32, bitcast=True),
                mask=jcols < OW,
            )
        else:
            tl.store(
                giw_ptr + off + 2 * jcols,
                tl.zeros((OWP,), dtype=tl.int32),
                mask=jcols < OW,
            )
            tl.store(
                giw_ptr + off + 2 * jcols + 1,
                v.to(tl.int32, bitcast=True),
                mask=jcols < OW,
            )


@triton.jit
def _exact3d_bwd_down_kernel(
    go_ptr,
    gi_ptr,
    C,
    Hi,
    Ho,
    sgo_n,
    sgo_c,
    sgo_d,
    sgo_h,
    sgi_n,
    sgi_c,
    sgi_d,
    sgi_h,
    KD: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    OW: tl.constexpr,
    OWP: tl.constexpr,
    R: tl.constexpr,
):
    """Integer downsampling in == out*k per dimension (general k, fallback path).

    Then fwd_x(j) = j*k + k//2 exactly (fp32 cannot round these values), so an
    input index i has at most ONE pre-image in each dimension:

        i = j*k + k//2  =>  j = (i - k//2) // k, valid iff (i - k//2) % k == 0

    Every grad_input element is therefore either grad_output[j] or 0.  One
    program owns R consecutive input rows of one (n, c, i_d) plane; each row is
    produced by a contiguous load, a (OWP, KW) column select and one contiguous
    store that also writes the zeros for positions without a pre-image, so every
    element is written exactly once.
    """
    ih0 = tl.program_id(0) * R
    id_ = tl.program_id(1)
    nc = tl.program_id(2)
    c = nc % C
    n = nc // C

    jd_num = id_ - (KD // 2)
    jd = jd_num // KD
    okd = (jd_num >= 0) & (jd_num % KD == 0)

    jcols = tl.arange(0, OWP)
    iw = tl.arange(0, OWP * KW)
    m_iw = iw < OW * KW
    kcol = tl.arange(0, KW)
    sel = (kcol == (KW // 2))[None, :]

    go_base = n * sgo_n + c * sgo_c + jd * sgo_d
    gi_base = n * sgi_n + c * sgi_c + id_ * sgi_d

    rmax = tl.minimum(R, Hi - ih0)
    for r in range(rmax):
        ih = ih0 + r
        hnum = ih - (KH // 2)
        jh = hnum // KH
        ok = okd & (hnum >= 0) & (hnum % KH == 0)
        jhc = tl.maximum(tl.minimum(jh, Ho - 1), 0)
        jjc = tl.minimum(jcols, OW - 1)
        v = tl.load(go_ptr + go_base + jhc * sgo_h + jjc)
        v = tl.where(ok, v, 0.0)
        v2 = tl.where(sel, v[:, None], 0.0)
        res = tl.reshape(v2, (OWP * KW,))
        tl.store(
            gi_ptr + gi_base + ih * sgi_h + iw,
            res.to(gi_ptr.dtype.element_ty),
            mask=m_iw,
        )


@triton.jit
def _exact3d_bwd_ratio_kernel(
    go_ptr,
    gi_ptr,
    Wi,
    C,
    Hi,
    Di,
    Do,
    Ho,
    Wo,
    sgo_n,
    sgo_c,
    sgo_d,
    sgo_h,
    sgo_w,
    sgi_n,
    sgi_c,
    sgi_d,
    sgi_h,
    sgi_w,
    W_TILES: tl.constexpr,
    BW: tl.constexpr,
    LCH: tl.constexpr,
    ACC16: tl.constexpr,
    IS_FP64: tl.constexpr,
):
    """General rational upsampling factor: exact integer pre-image intervals.

    All device memory accesses are contiguous vector loads; the many-to-one W
    mapping is resolved with a (BW, LCH) integer equality matrix instead of
    per-lane gather addresses (which are far slower on this target).  The grid is
    (W_TILES, Hi*Di, N*C) so a program needs only two index divisions, BW covers
    the whole input row whenever it fits (W_TILES == 1), LCH is sized host-side
    from the measured row span, and the (BW, LCH) accumulator is skipped for
    programs whose d/h pre-image window is empty.
    """
    pw = tl.program_id(0)
    row = tl.program_id(1)
    nc = tl.program_id(2)
    ih = row % Hi
    id_ = row // Hi
    c = nc % C
    n = nc // C

    lo_d = (2 * id_ * Do + Di - 1) // (2 * Di)
    hi_d = (2 * (id_ + 1) * Do + Di - 1) // (2 * Di)
    lo_h = (2 * ih * Ho + Hi - 1) // (2 * Hi)
    hi_h = (2 * (ih + 1) * Ho + Hi - 1) // (2 * Hi)

    iw = pw * BW + tl.arange(0, BW)
    m_iw = iw < Wi
    iws = tl.where(m_iw, iw, Wi - 1)
    lo_wv = (2 * iws * Wo + Wi - 1) // (2 * Wi)
    hi_wv = (2 * (iws + 1) * Wo + Wi - 1) // (2 * Wi)
    lo_w = tl.min(lo_wv)
    hi_w = tl.max(hi_wv)

    span = hi_w - lo_w
    n_c = (span + (LCH - 1)) // LCH
    n_d = hi_d - lo_d
    n_h = hi_h - lo_h

    go_base = n * sgo_n + c * sgo_c
    gi_off = n * sgi_n + c * sgi_c + id_ * sgi_d + ih * sgi_h + iw * sgi_w

    if IS_FP64:
        acc = tl.zeros((BW,), dtype=tl.float64)
    elif ACC16:
        acc = tl.zeros((BW,), dtype=gi_ptr.dtype.element_ty)
    else:
        acc = tl.zeros((BW,), dtype=tl.float32)

    if n_d * n_h > 0 and span > 0:
        if IS_FP64:
            acc2 = tl.zeros((BW, LCH), dtype=tl.float64)
        elif ACC16:
            acc2 = tl.zeros((BW, LCH), dtype=gi_ptr.dtype.element_ty)
        else:
            acc2 = tl.zeros((BW, LCH), dtype=tl.float32)

        for kd in range(n_d):
            od = lo_d + kd
            for kh in range(n_h):
                oh = lo_h + kh
                rowp = go_ptr + go_base + od * sgo_d + oh * sgo_h
                for cc in range(n_c):
                    ow = lo_w + cc * LCH + tl.arange(0, LCH)
                    v = tl.load(rowp + ow * sgo_w, mask=ow < Wo, other=0.0)
                    fwv = (2 * ow * Wi + Wi) // (2 * Wo)
                    eq = fwv[None, :] == iw[:, None]
                    if ACC16:
                        acc2 += tl.where(eq, v[None, :], 0.0)
                    elif IS_FP64:
                        acc2 += tl.where(eq, v[None, :], 0.0)
                    else:
                        acc2 += tl.where(eq, v.to(tl.float32)[None, :], 0.0)

        acc = tl.sum(acc2, axis=1)

    tl.store(gi_ptr + gi_off, acc.to(gi_ptr.dtype.element_ty), mask=m_iw)


@triton.jit
def _exact3d_bwd_gather_kernel(
    go_ptr,
    gi_ptr,
    total,
    C,
    Di,
    Hi,
    Wi,
    Do,
    Ho,
    Wo,
    sgo_n,
    sgo_c,
    sgo_d,
    sgo_h,
    sgo_w,
    sgi_n,
    sgi_c,
    sgi_d,
    sgi_h,
    sgi_w,
    s_d,
    s_h,
    s_w,
    r_d,
    r_h,
    r_w,
    BLOCK: tl.constexpr,
    IS_FP64: tl.constexpr,
):
    """Fallback for scales that disagree with out/in: exact fp32 ATen mapping.

    Windows are slack-extended and made exact by the fp32 forward-map predicate;
    every grad_input element is written exactly once (zeros included).
    """
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    m = idx < total
    idxs = tl.where(m, idx, total - 1)

    iw = idxs % Wi
    t = idxs // Wi
    ih = t % Hi
    t = t // Hi
    id_ = t % Di
    t = t // Di
    c = t % C
    n = t // C

    sd = s_d.to(tl.float32)
    sh = s_h.to(tl.float32)
    sw = s_w.to(tl.float32)
    rdv = r_d.to(tl.float32)
    rhv = r_h.to(tl.float32)
    rwv = r_w.to(tl.float32)

    fwi = iw.to(tl.float32)
    fhi = ih.to(tl.float32)
    fdi = id_.to(tl.float32)

    lo_w = tl.maximum(tl.ceil(fwi * rwv - 0.5) - 2.0, 0.0).to(tl.int32)
    hi_w = tl.minimum(tl.ceil((fwi + 1.0) * rwv - 0.5) + 2.0, Wo.to(tl.float32)).to(
        tl.int32
    )
    lo_h = tl.maximum(tl.ceil(fhi * rhv - 0.5) - 2.0, 0.0).to(tl.int32)
    hi_h = tl.minimum(tl.ceil((fhi + 1.0) * rhv - 0.5) + 2.0, Ho.to(tl.float32)).to(
        tl.int32
    )
    lo_d = tl.maximum(tl.ceil(fdi * rdv - 0.5) - 2.0, 0.0).to(tl.int32)
    hi_d = tl.minimum(tl.ceil((fdi + 1.0) * rdv - 0.5) + 2.0, Do.to(tl.float32)).to(
        tl.int32
    )

    kw_n = tl.maximum(tl.max(hi_w - lo_w), 0)
    kh_n = tl.maximum(tl.max(hi_h - lo_h), 0)
    kd_n = tl.maximum(tl.max(hi_d - lo_d), 0)

    if IS_FP64:
        acc = tl.zeros((BLOCK,), dtype=tl.float64)
    else:
        acc = tl.zeros((BLOCK,), dtype=tl.float32)

    base = n * sgo_n + c * sgo_c

    for kd in range(kd_n):
        jd = lo_d + kd
        md = m & (jd < hi_d)
        jdc = tl.minimum(jd, Do - 1)
        fdv = tl.minimum(tl.floor((jdc.to(tl.float32) + 0.5) * sd).to(tl.int32), Di - 1)
        md = md & (fdv == id_)
        for kh in range(kh_n):
            jh = lo_h + kh
            mh = md & (jh < hi_h)
            jhc = tl.minimum(jh, Ho - 1)
            fhv = tl.minimum(
                tl.floor((jhc.to(tl.float32) + 0.5) * sh).to(tl.int32), Hi - 1
            )
            mh = mh & (fhv == ih)
            for kw in range(kw_n):
                jw = lo_w + kw
                mw = mh & (jw < hi_w)
                jwc = tl.minimum(jw, Wo - 1)
                fwv = tl.minimum(
                    tl.floor((jwc.to(tl.float32) + 0.5) * sw).to(tl.int32), Wi - 1
                )
                mw = mw & (fwv == iw)
                addr = base + jdc * sgo_d + jhc * sgo_h + jwc * sgo_w
                v = tl.load(go_ptr + addr, mask=mw, other=0.0)
                if IS_FP64:
                    acc += v
                else:
                    acc += v.to(tl.float32)

    gi_off = n * sgi_n + c * sgi_c + id_ * sgi_d + ih * sgi_h + iw * sgi_w
    tl.store(gi_ptr + gi_off, acc.to(gi_ptr.dtype.element_ty), mask=m)


def _f32(x: float) -> float:
    """Round a Python double to float32, matching C's static_cast<float>."""
    return struct.unpack("f", struct.pack("f", x))[0]


def _int_factor(out_size: int, in_size: int, scale) -> int:
    """Return k when the exact pre-image of input i is [i*k, (i+1)*k), else 0."""
    if in_size <= 0 or out_size < in_size:
        return 0
    if out_size % in_size != 0:
        return 0
    k = out_size // in_size
    if scale is not None:
        sv = float(scale)
        if sv > 0.0 and (sv != float(k) or _f32(k) != sv):
            return 0
    return k


def _size_consistent(scale, in_size: int, out_size: int) -> bool:
    """True when the interval scale can be expressed as the exact rational out/in."""
    if scale is None:
        return True
    sv = float(scale)
    if sv <= 0.0:
        return True
    if in_size <= 0:
        return False
    return sv == float(out_size) / float(in_size)


def _down_factor(out_size: int, in_size: int, scale) -> int:
    """Return k when in == out*k (integer downsampling), else 0."""
    if out_size <= 0 or in_size < out_size:
        return 0
    if in_size % out_size != 0:
        return 0
    if not _size_consistent(scale, in_size, out_size):
        return 0
    return in_size // out_size


def _scale_pair(scale, in_size: int, out_size: int):
    """(forward map scale in/out, interval scale out/in) in float32."""
    if scale is not None and float(scale) > 0.0:
        sv = float(scale)
        return _f32(1.0 / sv), _f32(sv)
    if in_size <= 0 or out_size <= 0:
        return 0.0, 0.0
    return _f32(in_size / out_size), float(out_size) / float(in_size)


def upsample_nearest_exact3d_backward_grad_input(
    grad_output: torch.Tensor,
    output_size: Tuple[int, int, int],
    input_size: Tuple[int, int, int, int, int],
    scales_d: Optional[float] = None,
    scales_h: Optional[float] = None,
    scales_w: Optional[float] = None,
    grad_input: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    go = grad_output
    if go.ndim != 5:
        raise RuntimeError("grad_output must be a 5D tensor")
    if len(output_size) != 3:
        raise RuntimeError("output_size must contain three values")
    if len(input_size) != 5:
        raise RuntimeError("input_size must contain five values")

    od = int(output_size[0])
    oh = int(output_size[1])
    ow = int(output_size[2])
    n = int(input_size[0])
    c = int(input_size[1])
    di = int(input_size[2])
    hi = int(input_size[3])
    wi = int(input_size[4])
    if (
        go.shape[0] != n
        or go.shape[1] != c
        or go.shape[2] != od
        or go.shape[3] != oh
        or go.shape[4] != ow
    ):
        raise RuntimeError("grad_output shape does not match output_size/input_size")

    gi = grad_input
    if gi is None:
        gi = torch.empty((n, c, di, hi, wi), dtype=go.dtype, device=go.device)
    else:
        if gi.dtype != go.dtype:
            raise RuntimeError(
                f"Expected out tensor to have dtype {go.dtype}, but got {gi.dtype} instead"
            )
        if gi.device != go.device:
            raise RuntimeError("grad_input and grad_output must be on the same device")
        if (
            gi.shape[0] != n
            or gi.shape[1] != c
            or gi.shape[2] != di
            or gi.shape[3] != hi
            or gi.shape[4] != wi
        ):
            gi.resize_((n, c, di, hi, wi))

    total = n * c * di * hi * wi
    if total == 0:
        return gi

    is_fp64 = go.dtype == torch.float64

    fd = _int_factor(od, di, scales_d)
    fh = _int_factor(oh, hi, scales_h)
    fw = _int_factor(ow, wi, scales_w)

    if (
        fd
        and fh
        and fw
        and go.is_contiguous()
        and gi.is_contiguous()
        and od < 8388608
        and oh < 8388608
        and ow < 8388608
    ):
        bw = 1 << (wi - 1).bit_length()
        if bw > 512:
            bw = 512
        wt = (wi + bw - 1) // bw
        fwp = 1 << (fw - 1).bit_length()
        go_c = od * oh * ow
        gi_c = di * hi * wi
        _exact3d_bwd_int_kernel[(wt * di * hi * n * c,)](
            go,
            gi,
            wi,
            wt,
            c,
            hi,
            di,
            c * go_c,
            go_c,
            oh * ow,
            ow,
            c * gi_c,
            gi_c,
            hi * wi,
            wi,
            1,
            fd,
            fh,
            fw,
            fwp,
            fwp == fw,
            bw,
            (wi % bw) == 0,
            is_fp64,
        )
        return gi

    if (
        _size_consistent(scales_d, di, od)
        and _size_consistent(scales_h, hi, oh)
        and _size_consistent(scales_w, wi, ow)
    ):
        kd = _down_factor(od, di, scales_d)
        kh = _down_factor(oh, hi, scales_h)
        kw = _down_factor(ow, wi, scales_w)
        if (
            kd
            and kh
            and kw
            and (kw & (kw - 1)) == 0
            and go.stride(-1) == 1
            and gi.stride(-1) == 1
            and od < 8388608
            and oh < 8388608
            and ow < 8388608
        ):
            owp = 1 << (ow - 1).bit_length()
            rows = hi * di * n * c
            r = rows // 8192
            if r > hi:
                r = hi
            if r > 64:
                r = 64
            if r < 1:
                r = 1
            grid = ((hi + r - 1) // r, di, n * c)
            if (
                kw == 2
                and gi.is_contiguous()
                and go.dtype in (torch.float32, torch.float16, torch.bfloat16)
            ):
                giw = gi.view(torch.int32)
                _exact3d_bwd_down_pack_kernel[grid](
                    go,
                    giw,
                    c,
                    hi,
                    oh,
                    go.stride(0),
                    go.stride(1),
                    go.stride(2),
                    go.stride(3),
                    giw.stride(0),
                    giw.stride(1),
                    giw.stride(2),
                    giw.stride(3),
                    kd,
                    kh,
                    ow,
                    owp,
                    1 if go.dtype == torch.float32 else 0,
                    r,
                )
                return gi
            if owp * kw <= 4096:
                _exact3d_bwd_down_kernel[grid](
                    go,
                    gi,
                    c,
                    hi,
                    oh,
                    go.stride(0),
                    go.stride(1),
                    go.stride(2),
                    go.stride(3),
                    gi.stride(0),
                    gi.stride(1),
                    gi.stride(2),
                    gi.stride(3),
                    kd,
                    kh,
                    kw,
                    ow,
                    owp,
                    r,
                )
                return gi
        rw = float(ow) / float(wi)
        bw = 1 << (wi - 1).bit_length()
        cap = 64 if rw >= 1.0 else 16
        if bw > cap:
            bw = cap
        wt = (wi + bw - 1) // bw
        lch = 16
        span_est = int(bw * rw) + 3
        if span_est > 16:
            lch = 32
            while lch < span_est and lch < 128:
                lch *= 2
        acc16 = 1 if (go.dtype in (torch.float16, torch.bfloat16) and lch >= 32) else 0
        _exact3d_bwd_ratio_kernel[(wt, hi * di, n * c)](
            go,
            gi,
            wi,
            c,
            hi,
            di,
            od,
            oh,
            ow,
            go.stride(0),
            go.stride(1),
            go.stride(2),
            go.stride(3),
            go.stride(4),
            gi.stride(0),
            gi.stride(1),
            gi.stride(2),
            gi.stride(3),
            gi.stride(4),
            wt,
            bw,
            lch,
            acc16,
            is_fp64,
        )
        return gi

    sd, rd = _scale_pair(scales_d, di, od)
    sh, rh = _scale_pair(scales_h, hi, oh)
    sw, rw = _scale_pair(scales_w, wi, ow)
    block = 128
    _exact3d_bwd_gather_kernel[((total + block - 1) // block,)](
        go,
        gi,
        total,
        c,
        di,
        hi,
        wi,
        od,
        oh,
        ow,
        go.stride(0),
        go.stride(1),
        go.stride(2),
        go.stride(3),
        go.stride(4),
        gi.stride(0),
        gi.stride(1),
        gi.stride(2),
        gi.stride(3),
        gi.stride(4),
        sd,
        sh,
        sw,
        rd,
        rh,
        rw,
        block,
        is_fp64,
    )
    return gi
